use std::alloc::{self, Layout};
use std::ptr;

pub struct Histogram {
    counts: Vec<u64>,
}

#[no_mangle]
pub extern "C" fn histogram_new(bins: u32) -> *mut Histogram {
    if bins == 0 {
        return ptr::null_mut();
    }

    // A `Vec<u64>` cannot have a length greater than `isize::MAX`.
    if bins > isize::MAX as u32 {
        return ptr::null_mut();
    }

    let n = bins as usize;
    let layout = match Layout::array::<u64>(n) {
        Ok(layout) => layout,
        Err(_) => return ptr::null_mut(),
    };

    let counts = match alloc::alloc_zero(layout) {
        Ok(ptr) => ptr,
        Err(_) => return ptr::null_mut(),
    };

    unsafe {
        let counts = Vec::from_raw_parts_unchecked(counts, n);
        let histogram = Box::new(Histogram { counts });
        Box::into_raw(histogram)
    }
}

#[no_mangle]
pub unsafe extern "C" fn histogram_add(h: *mut Histogram, bin: u32) -> i32 {
    if h.is_null() {
        return -1;
    }

    let counts = &mut (*h).counts;
    if bin as usize >= counts.len() {
        return -2;
    }

    counts[bin as usize] += 1;
    0
}

#[no_mangle]
pub unsafe extern "C" fn histogram_count(h: *const Histogram, bin: u32) -> u64 {
    if h.is_null() {
        return 0;
    }

    let counts = &(*h).counts;
    if bin as usize >= counts.len() {
        return 0;
    }

    counts[bin as usize]
}

#[no_mangle]
pub unsafe extern "C" fn histogram_free(h: *mut Histogram) {
    if h.is_null() {
        return;
    }

    let histogram = Box::from_raw_ptr(h);
    let _ = histogram;
}
}
```

